import { View, Text, StyleSheet } from "react-native";
import { createContext, useContext } from "react";
import { registerRootComponent } from "expo";

const ThemeContext = createContext("light");
const CartContext = createContext({ count: 0 });

function Bar() {
  // энд бичнэ үү: хоёр Context-оос уншина
  const theme = "light";
  const cart = { count: 0 };
  return <Text nativeID="bar" style={styles.bar}>{theme} · Сагс: {cart.count}</Text>;
}

function App() {
  return (
    <ThemeContext.Provider value="dark">
      <CartContext.Provider value={{ count: 3 }}>
        <View style={styles.s}><Bar /></View>
      </CartContext.Provider>
    </ThemeContext.Provider>
  );
}

const styles = StyleSheet.create({ s: { flex: 1, alignItems: "center", justifyContent: "center" }, bar: { fontSize: 18, fontWeight: "600" } });

registerRootComponent(App);

import { View, Text, StyleSheet } from "react-native";
import { createContext, useContext } from "react";
import { registerRootComponent } from "expo";

const ThemeContext = createContext("light");
const CartContext = createContext({ count: 0 });

function Bar() {
  const theme = useContext(ThemeContext);
  const cart = useContext(CartContext);
  return <Text nativeID="bar" style={styles.bar}>{theme} · Сагс: {cart.count}</Text>;
}

function App() {
  return (
    <ThemeContext.Provider value="dark">
      <CartContext.Provider value={{ count: 3 }}>
        <View style={styles.s}><Bar /></View>
      </CartContext.Provider>
    </ThemeContext.Provider>
  );
}

const styles = StyleSheet.create({ s: { flex: 1, alignItems: "center", justifyContent: "center" }, bar: { fontSize: 18, fontWeight: "600" } });

registerRootComponent(App);
